CREATE TABLE game (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,resource_id UUID NOT NULL,game_kind VARCHAR(32),version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(resource_id) REFERENCES resource(id),UNIQUE(owner_id,resource_id));
CREATE TABLE game_platform (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,name VARCHAR(128) NOT NULL,family VARCHAR(128),architecture VARCHAR(64),UNIQUE(owner_id,name));
CREATE TABLE game_version (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,game_id UUID NOT NULL,platform_id UUID,version_label VARCHAR(256) NOT NULL,release_date TIMESTAMPTZ,version BIGINT NOT NULL DEFAULT 0,FOREIGN KEY(game_id) REFERENCES game(id) ON DELETE CASCADE,FOREIGN KEY(platform_id) REFERENCES game_platform(id));
CREATE TABLE game_asset (id UUID PRIMARY KEY DEFAULT uuid_v7(),owner_id UUID NOT NULL,game_id UUID NOT NULL,version_id UUID,attachment_id UUID NOT NULL,category VARCHAR(32) NOT NULL,display_name VARCHAR(512),checksum_algorithm VARCHAR(32),checksum_value VARCHAR(256),availability VARCHAR(24) NOT NULL DEFAULT 'AVAILABLE',entity_version BIGINT NOT NULL DEFAULT 0,CHECK(category IN ('INSTALLER','PATCH','MOD','SAVE','MANUAL','SCREENSHOT','OTHER')),CHECK(availability IN ('AVAILABLE','ARCHIVED','RESTORING','MISSING','CORRUPTED')),FOREIGN KEY(game_id) REFERENCES game(id) ON DELETE CASCADE,FOREIGN KEY(version_id) REFERENCES game_version(id),FOREIGN KEY(attachment_id) REFERENCES attachment(id),UNIQUE(game_id,attachment_id));
CREATE INDEX idx_game_asset_category ON game_asset(owner_id,game_id,category,availability);
